from ute_common_converter.to_number import to_int
from ute_common_validator.validator import IsString, IsOneOf

from ...config import ENBConfig

from .base_cl_tool import BaseClToolInterface


class CellOperationInterface(BaseClToolInterface):
    """Keywords related to BTS cells."""

    def block_cell(self, cellid, priority='normal', id_type='global', timeout='5min', **kwargs):
        """Block cell.

        :param integer cellid: Global cell id/id's. Multiple cells should be separated by commas or single space.
        :param string priority: Priority for the operation. Supported values are: low, normal, high.
        :param string id_type: Value specified type of provided cell ID. Supported values are: global, local.

        :return: Path(s) of collected file(s).
        :rtype: list
        """
        cellid = self._get_cell_ids(str(cellid))
        alias = kwargs.get('alias')
        alias = alias.strip() if alias else None
        id_type = id_type.strip()
        priority = priority.strip()
        self._check_id_type_value(id_type)
        self._check_priority_value(priority)
        timeout = self._convert_to_secs(timeout)
        config = self.command_store.get(alias).get_config()
        ne = kwargs.get('ne', config.trs_ip).strip()
        pw = kwargs.get('pw', config.pw).strip()
        params = self._find_cell_operation_params(cellid, id_type, ne, pw, priority, timeout)
        nolog = config.nolog if kwargs.get('nolog') is None else kwargs.get('nolog')
        flags = ['nolog'] if nolog else []
        return self._execute_cl_tool_operation(alias=alias, timeout=timeout, operation='blockcell', params=params, trs_ip=ne, flags=flags)

    def unblock_cell(self, cellid, priority='normal', id_type='global', timeout='5min', **kwargs):
        """Unblock cell.

        :param integer cellid: Global cell id/id's. Multiple cells should be separated by commas or single space.
        :param string priority: Priority for the operation.
                                Supported values are: low, normal, high.
        :param string id_type: Value specified type of provided cell ID.
                               Supported values are: global, local.

        :return: Path(s) of collected file(s).
        :rtype: list
        """
        cellid = self._get_cell_ids(str(cellid))
        alias = kwargs.get('alias')
        alias = alias.strip() if alias else None
        id_type = id_type.strip()
        priority = priority.strip()
        self._check_id_type_value(id_type)
        self._check_priority_value(priority)
        timeout = self._convert_to_secs(timeout)
        config = self.command_store.get(alias).get_config()
        ne = kwargs.get('ne', config.trs_ip).strip()
        pw = kwargs.get('pw', config.pw).strip()
        params = self._find_cell_operation_params(cellid, id_type, ne, pw, priority, timeout)
        nolog = config.nolog if kwargs.get('nolog') is None else kwargs.get('nolog')
        flags = ['nolog'] if nolog else []
        return self._execute_cl_tool_operation(alias=alias, timeout=timeout, operation='unblockcell', params=params, trs_ip=ne, flags=flags)

    def _get_cell_ids(self, cellid):
        ids = [str(to_int(id)) for id in filter(bool, cellid.replace(' ', ',').split(','))]
        return ','.join(ids)

    def _find_cell_operation_params(self, cellid, id_type, ne, pw, priority, timeout):
        cell_type_name = "{}id".format(id_type)
        return {cell_type_name: cellid, 'ne': ne, 'pw': pw, 'priority': priority, 'timeout': timeout}

    def _check_priority_value(self, priority):
        IsString().check(priority)
        IsOneOf('low', 'normal', 'high').check(priority)

    def _check_id_type_value(self, id_type):
        IsString().check(id_type)
        IsOneOf('global', 'local').check(id_type)
